<?php require __DIR__.'/includes/bootstrap.php';$adminSetupNeeded=!(bool)$pdo->query("SELECT 1 FROM users WHERE role='admin' LIMIT 1")->fetchColumn();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT id,nom,email,password,role FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);unset($u['password']);$_SESSION['user']=$u;redirect('/dashboard.php');}$error='Email ou mot de passe incorrect.';}$title='Connexion';require __DIR__.'/includes/header.php';?>
